[Feed(SourceSystem = typeof(StudentInformationSystem))]
public class CourseFeed : IFeed<Course>
{
    private readonly SisFactory factory;
    public CourseFeed(SisFactory factory) => this.factory = factory;

    public IEntityCollection<Course> LoadEntities()
    {
        using var ctx = this.factory.CreateContext();
        return ctx.Courses
            .Select(c => new Course { Code = c.Id, CourseNumber = c.Number, Title = c.Name })
            .ToList();
    }
}
